"use client";

import { forwardRef, type HTMLAttributes } from "react";
import { Button as AriaButton } from "react-aria-components";
import { markerDefaults, type MarkerSpecProps } from "../generated/marker.types";
import { cx } from "../utils/cx";

export interface MarkerProps
  extends MarkerSpecProps,
    Omit<HTMLAttributes<HTMLDivElement>, keyof MarkerSpecProps | "className" | "children" | "role"> {
  className?: string;
}

/**
 * A labelled divider inside a conversation. On its own it is a separator named by its label. With
 * onJump it is a labelled group holding a real button, since a separator cannot contain controls.
 */
export const Marker = forwardRef<HTMLDivElement, MarkerProps>(function Marker(
  { label, variant = markerDefaults.variant, dateTime, onJump, jumpLabel, className, ...rest },
  ref,
) {
  const unread = variant === "unread";
  const jump = unread && !!onJump;
  const lineClass = cx("h-px flex-1", unread ? "bg-[var(--rd-color-action-primary)]" : "bg-[var(--rd-color-border-default)]");
  const textClass = cx(
    "shrink-0 text-center text-xs",
    variant !== "event" && "font-medium",
    unread ? "text-[var(--rd-color-action-primary)]" : "text-[var(--rd-color-text-muted)]",
  );
  const text = dateTime ? <time dateTime={dateTime}>{label}</time> : label;

  return (
    <div
      {...rest}
      ref={ref}
      role={jump ? "group" : "separator"}
      aria-label={label}
      data-variant={variant}
      className={cx("flex w-full items-center gap-3 py-1", className)}
    >
      <span aria-hidden="true" className={lineClass} />
      {jump ? (
        <AriaButton
          onPress={onJump}
          aria-label={jumpLabel}
          className={cx(
            textClass,
            "min-h-6 rounded-[var(--rd-radius-control)] px-2 py-0.5 outline-none data-[hovered]:underline data-[focus-visible]:ring-2 data-[focus-visible]:ring-[var(--rd-color-focus-ring)]",
          )}
        >
          {text}
        </AriaButton>
      ) : (
        <span className={textClass}>{text}</span>
      )}
      <span aria-hidden="true" className={lineClass} />
    </div>
  );
});

// Generated by rdloom codegen from specs/marker.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

export const markerVariantValues = ["date", "unread", "event"] as const;

/** A divider that labels a moment inside a conversation or feed: a centered label between two lines. Use date for a new day, unread for where new messages start, and event for something that happened, like someone joining. */
export interface MarkerSpecProps {
  /**
   * The text, e.g. "Today", "New messages" or "Alex joined".
   */
  label: string;
  /**
   * date is neutral. unread uses the action colour for the label and lines. event is a smaller, muted note.
   * @default "date"
   */
  variant?: "date" | "unread" | "event";
  /**
   * A machine readable date for a date marker, e.g. "2026-10-08". The label becomes a time element.
   */
  dateTime?: string;
  /**
   * Turns the label of an unread marker into a button, e.g. to scroll to the first new message.
   */
  onJump?: () => void;
  /**
   * Accessible name of the jump button when it needs more than the label, e.g. "Jump to first new message".
   */
  jumpLabel?: string;
}

export const markerDefaults = {
  variant: "date",
} as const;

export const markerMeta = {
  "name": "Marker",
  "version": "0.1.0",
  "status": "experimental",
  "role": "separator"
} as const;
